SELECT DISTINCT l.ref_market_id FROM ledger_entry l JOIN ledger_account a ON a.id = l.account_id
WHERE a.user_id = #{userId} AND l.entry_type = 'PAYOUT' AND l.ref_market_id IS NOT NULL AND l.created_at >= #{since}
ORDER BY l.ref_market_id

SELECT 
FROM ledger_entry l JOIN ledger_account a ON a.id = l.account_id
WHERE a.user_id = #{userId} AND l.bucket = 'AVAILABLE' ORDER BY l.id DESC LIMIT #{limit}

